import { defineComponent } from "vue";
import { IPublicFramePortalType } from "../../../types";

export const FloatingSystemMessage = defineComponent({
  name: "FloatingSystemMessage",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup() {
    return () => {
      return (
        <div class="floating-system-message layout-floating-item">
          <el-icon class={["layout-floating-item__icon iconfont icon-a-bell"]}></el-icon>
          <span class="layout-floating-item__title">
            动态
          </span>
        </div>
      );
    };
  },
});
