import type { PropType, VNode } from "vue";
import { computed, defineComponent, h, onMounted, ref } from "vue";
import { useCsNamespace } from "../../hooks/use-namespace";
import { PluginManager } from "../../plugins/layout-plugin/plugin-manage/plugin-manager";
import {
  PluginInstance,
  pluginPosition,
  PluginPositionKey,
} from "../../plugins/layout-plugin/plugin-manage/plugin-type";
import { IPublicFramePortalType } from "../../types";
import { webFrameworkEvent } from "../../utils/web-framework-event";
import "./layout-header-style.less";

export const LayoutHeader = defineComponent({
  name: "LayoutHeader",
  props: {
    pluginManager: {
      type: Object as PropType<PluginManager>,
      required: true,
    },
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(props) {
    const ns = useCsNamespace("entrypoint-header");
    const activeDropdown = ref<string | null>(null);
    const plugins = computed(() => {
      return [
        ...props.pluginManager.getPluginsByPosition(pluginPosition.HEADER_LEFT),
        ...props.pluginManager.getPluginsByPosition(pluginPosition.HEADER_CENTER),
        ...props.pluginManager.getPluginsByPosition(pluginPosition.HEADER_RIGHT),
      ];
    });

    // 按位置分组插件
    const getPluginsByPosition = (position: PluginPositionKey) => {
      const posPlugins = plugins.value.filter(plugin => plugin.config.position === position);
      posPlugins.sort((a, b) => {
        return (a.config.sort || 0) - (b.config.sort || 0);
      });
      return posPlugins;
    };

    // 处理插件点击
    const handlePluginClick = (plugin: PluginInstance, e: Event) => {
      e.stopPropagation();

      // 触发全局事件
      webFrameworkEvent.emit(`plugin.click.${plugin.id}`, plugin);

      // 调用插件自身的点击处理
      if (plugin.config?.onClick) {
        plugin.config?.onClick(plugin.id);
      }
    };

    // 关闭所有下拉框
    const closeAllDropdowns = () => {
      activeDropdown.value = null;
    };

    // 点击文档其他区域关闭下拉框
    onMounted(() => {
      document.addEventListener("click", closeAllDropdowns);

      return () => {
        document.removeEventListener("click", closeAllDropdowns);
      };
    });

    // 渲染插件
    const renderPlugin = (plugin: PluginInstance): VNode => {
      return (
        <div class={[ns.e("plugin-render"), plugin.id]}>
          {h(plugin.component, {
            config: plugin.config,
            onClick: (e: Event) => handlePluginClick(plugin, e),
          })}
        </div>
      );
    };

    return () => {
      return (
        <div class={ns.b()}>
          <div class={ns.e("left")}>
            {getPluginsByPosition(pluginPosition.HEADER_LEFT).map(plugin => renderPlugin(plugin))}
          </div>
          <div class={ns.e("center")}>
            {getPluginsByPosition(pluginPosition.HEADER_CENTER).map(plugin => renderPlugin(plugin))}
          </div>
          <div class={ns.e("right")}>
            {getPluginsByPosition(pluginPosition.HEADER_RIGHT).map(plugin => renderPlugin(plugin))}
          </div>
        </div>
      );
    };
  },
});
