import type { AxiosError, AxiosInstance, AxiosRequestConfig, AxiosResponse, CancelTokenSource, InternalAxiosRequestConfig } from "axios";
import axios from "axios";
import { portalBridge } from "../plugins";

// 自定义响应类型接口
export interface CustomResponse<T = any> {
  code: number;
  message: string;
  result: T;
  status: "success" | "error" | "fail";
}

export interface CustomErrorResponse {
  code: number;
  message: string;
  path: string;
  timestamp: Date;
}

// 请求取消管理器
export class RequestCancelManager {
  private pendingRequests: Map<string, CancelTokenSource> = new Map();

  /**
   * 生成请求的唯一标识
   */

  private generateRequestKey(config: AxiosRequestConfig): string {
    const { method, url, params, data } = config;
    return `${method}-${url}-${JSON.stringify(params)}-${JSON.stringify(data)}`;
  }

  /**
   * 添加待处理的请求
   */
  public addPendingRequest(config: AxiosRequestConfig): CancelTokenSource {
    const requestKey = this.generateRequestKey(config);
    const source = axios.CancelToken.source();
    this.pendingRequests.set(requestKey, source);
    return source;
  }

  /**
   * 移除待处理的请求
   */
  public removePendingRequest(config: AxiosRequestConfig): void {
    const requestKey = this.generateRequestKey(config);
    this.pendingRequests.delete(requestKey);
  }

  /**
   * 取消指定的请求
   */
  public cancelRequest(config: AxiosRequestConfig, message?: string): void {
    const requestKey = this.generateRequestKey(config);
    const source = this.pendingRequests.get(requestKey);
    if (source) {
      source.cancel(message || "请求已取消");
      this.pendingRequests.delete(requestKey);
    }
  }

  /**
   * 取消所有待处理的请求
   */
  public cancelAllRequests(message?: string): void {
    this.pendingRequests.forEach((source) => {
      source.cancel(message || "所有请求已取消");
    });
    this.pendingRequests.clear();
  }

  /**
   * 获取待处理请求的数量
   */
  public getPendingRequestCount(): number {
    return this.pendingRequests.size;
  }

  /**
   * 清空所有待处理的请求（不取消）
   */
  public clearPendingRequests(): void {
    this.pendingRequests.clear();
  }
}

const defaultTimeout = 15 * 1000;
class AxiosWrapper {
  private static instance: AxiosWrapper;
  axiosInstance: AxiosInstance;
  public cancelManager: RequestCancelManager;
  private enableRequestCancel: boolean = false;

  private constructor() {
    this.axiosInstance = axios.create({
      baseURL: "",
      timeout: defaultTimeout,
    });

    this.cancelManager = new RequestCancelManager();
    this.setupInterceptors();
  }

  public static getInstance(): AxiosWrapper {
    if (!AxiosWrapper.instance) {
      AxiosWrapper.instance = new AxiosWrapper();
    }
    return AxiosWrapper.instance;
  }

  public setupInterceptors() {
    this.axiosInstance.interceptors.request.use(
      (config: InternalAxiosRequestConfig) => {
        // 如果启用了请求取消功能，则添加 cancel token
        if (this.enableRequestCancel) {
          const source = this.cancelManager.addPendingRequest(config);
          config.cancelToken = source.token;
        }
        // 请求拦截逻辑
        return config;
      },
      (error) => {
        return Promise.reject(error);
      },
    );

    this.axiosInstance.interceptors.response.use(
      (response: AxiosResponse<CustomResponse>) => {
        // 请求成功后，从待处理列表中移除
        if (this.enableRequestCancel) {
          this.cancelManager.removePendingRequest(response.config);
        }
        // 响应拦截逻辑
        return response;
      },
      (error: AxiosError<CustomErrorResponse & { redirectUrl?: string }>) => {
        // 请求失败后，从待处理列表中移除
        if (this.enableRequestCancel && error.config) {
          this.cancelManager.removePendingRequest(error.config);
        }

        // session 过期：后端返回 401 + { code: 302, redirectUrl }，跳转到登录页
        const data = error.response?.data;
        if (error.response?.status === 401 && data?.code === 302 && data?.redirectUrl) {
          // window.open(data.redirectUrl, "_self");
          portalBridge.redirectLogin({ loginUrl: data.redirectUrl });
          return new Promise(() => {});
        }

        return Promise.reject(error);
      },
    );
  }

  public setHeaders(headers: Record<string, string | boolean | number>) {
    Object.assign(this.axiosInstance.defaults.headers.common, headers);
  }

  /**
   * 启用自动请求取消功能
   */
  public enableAutoCancel(): void {
    this.enableRequestCancel = true;
  }

  /**
   * 禁用自动请求取消功能
   */
  public disableAutoCancel(): void {
    this.enableRequestCancel = false;
  }

  /**
   * 创建可取消的请求配置
   */

  public createCancelableConfig(config?: AxiosRequestConfig): AxiosRequestConfig & { cancelToken: any } {
    const source = axios.CancelToken.source();
    return {
      ...config,
      cancelToken: source.token,
      // 将 source 附加到配置上，方便后续取消
      __cancelSource: source,
    } as any;
  }

  /**
   * 取消指定配置的请求
   */
  public cancelRequestByConfig(config: AxiosRequestConfig, message?: string): void {
    this.cancelManager.cancelRequest(config, message);
  }

  /**
   * 取消所有待处理的请求
   */
  public cancelAllRequests(message?: string): void {
    this.cancelManager.cancelAllRequests(message);
  }

  /**
   * 判断错误是否为取消错误
   */

  public isCancel(error: any): boolean {
    return axios.isCancel(error);
  }

  public async get<T = any, R = CustomResponse<T>>(url: string, config?: AxiosRequestConfig): Promise<R> {
    const response = await this.axiosInstance.get<R>(url, config);
    return response.data;
  }

  public async post<T = any, D = any, R = CustomResponse<T>>(
    url: string,
    data?: D,
    config?: AxiosRequestConfig,
  ): Promise<R> {
    const response = await this.axiosInstance.post<R>(url, data, config);
    return response.data;
  }

  public async put<T = any, D = any, R = CustomResponse<T>>(
    url: string,
    data?: D,
    config?: AxiosRequestConfig,
  ): Promise<R> {
    const response = await this.axiosInstance.put<R>(url, data, config);
    return response.data;
  }

  public async delete<T = any, D = any, R = CustomResponse<T>>(
    url: string,
    data?: D,
    config?: AxiosRequestConfig,
  ): Promise<R> {
    const _config = {
      data,
      ...config,
    };
    const response = await this.axiosInstance.delete<R>(url, _config);
    return response.data;
  }
}

export const $http = AxiosWrapper.getInstance();
