import type { IPublicApplicationType, IPublicContextStateType, IPublicMenuType, IPublicOrgNodeType } from "../types";
import { $http } from "../index";
import { CustomResponse } from "../utils/request";

export const apiPortal = {
  /**
	 * 初始化上下文接口
	 * @param params
	 */
  initContext: (params: Record<string, any>): Promise<CustomResponse<IPublicContextStateType>> => {
    return $http.get<IPublicContextStateType>("/pmShare/pm-metadata-api/module-context", params);
  },
  /**
	 * portal上下文初始化，简单、快捷
	 * @param params
	 */
  portalInit: (params: Record<string, any>) => {
    return $http.get<IPublicContextStateType>("/pmShare/pm-metadata-api/portal-init", params);
  },
  /**
	 * 查询菜单接口
	 * @param params
	 */
  queryMenu: (params: Record<string, any>) => {
    return $http.get<IPublicMenuType[]>("/pmShare/pm-metadata-api/menus", params);
  },
  /**
	 * 查询组织接口
	 * @param params
	 */
  queryOrg: <T = IPublicOrgNodeType>(params: Record<string, any>) => {
    return $http.get<T>("/pmShare/pm-metadata-api/org-nodes", params);
  },
  /**
	 * 查询用户应用接口
	 * @param params
	 */
  queryUserApplications: (params: Record<string, any>) => {
    return $http.get<IPublicApplicationType[]>("/pmShare/pm-metadata-api/applications?appType=web", params);
  },
  /**
	 * 加载组织接口
	 * @param params
	 */
  loadPortalOrgNode: (params: Record<string, any>) => {
    return $http.get("/pmShare/pm-metadata-api/org-nodes", params);
  },

  /**
	 * 获取用户有权限的组织机构树
	 * @param {Record<string, any>} params
	 * @returns {Promise<CustomResponse<any>>}
	 */
  getUserValidOrgTrees: <T = any[]>(params: Record<string, any>) => {
    return $http.get<T>("/pmShare/pm-metadata-api/user-valid-org-nodes", params);
  },
  /**
	 * 查询用户配置接口
	 * @param params
	 */
  queryPortalConfig: (params: Record<string, any>) => {
    return $http.get("/portal/workstation/query-portal-config", params);
  },

  /**
	 * 保存模块访问历史记录
	 * @param {Record<string, any>} params
	 * @returns {Promise<CustomResponse<any>>}
	 */
  accessHistory: <T = any>(params: Record<string, any>) => {
    return $http.post<T>("/pmShare/user-behavior/access-history", params);
  },
  /**
	 * 获取portal使用的配置
	 * @param {Record<string, any>} params
	 * @returns {Promise<CustomResponse<T>>}
	 */
  queryPortalTabsConfig: <T = any>() => {
    return $http.get<T>("/portal/workstation/query-portal-tabs-config");
  },
};
