import { ElMessage } from "element-plus";
import { get } from "lodash-es";
import { computed, defineComponent } from "vue";
import { useCsNamespace } from "../../../hooks/use-namespace";
import { $http, urlUtil } from "../../../index-kanban";
import { IPublicFramePortalType } from "../../../types";
import defaultUser from "./default-user.png";
import "./account-management-style.less";

/**
 * 账户管理账户管理
 */
export const AccountManagement = defineComponent({
  name: "AccountManagement",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(props) {
    const ns = useCsNamespace("account-management-widget");
    const userAvatarUrl = computed(() => {
      return props.frameStore.$context.userAvatarUrl || defaultUser;
    });

    async function logout() {
      const res = await $http.get<any, { status: string; redirectUrl?: string }>("/logout");
      if (res.status === "success") {
        location.href = res.redirectUrl || `/login.html`;
      }
    }

    function goUserCenter() {
      const userSettingUrl = get(props.frameStore, "portalConfig.userSettingUrl");
      if (!userSettingUrl) {
        ElMessage.error("用户中心地址未配置");
      }
      const params = urlUtil.extractUrlParams(userSettingUrl).searchParams;
      /* tabManager.addTab({
        menuId: params.menuId,
        menuName: "个人中心",
        moduleId: params.moduleId,
        moduleUrl: "/portal/user-setting.html",
        applicationId: params.applicationId,
        applicationName: "门户管理",
        closable: true,
      } as any); */
      // openCurAppModule({ moduleCode: "user-setting", prefix: "portal" }, true);
    }

    const handleCommand = (command: string) => {
      if (command === "logout") {
        logout();
      }

      if (command === "passChange") {
        window.open("/password-reset.html", "_blank");
      }

      if (command === "changeTenant") {
        window.location.href = "/tenants.html";
      }

      if (command === "userCenter") {
        goUserCenter();
      }
    };

    return () => {
      return (
        <div class={ns.b()}>
          <el-dropdown
            trigger="click"
            onCommand={handleCommand}
            class={ns.b("dropdown")}
          >
            {{
              default: () => {
                return (
                  <div class={ns.b("avatar")}>
                    <el-icon
                      size="18"
                      class={ns.be("avatar", "icon")}
                    >
                      <img
                        src={userAvatarUrl.value}
                        alt="用户图像"
                        width={24}
                        height={24}
                      />
                    </el-icon>
                    <span class={ns.e("realname")}>
                      {props.frameStore.$context.realName}
                    </span>
                  </div>
                );
              },
              dropdown: () => {
                return (
                  <el-dropdown-menu>
                    <el-dropdown-item command="passChange">
                      重置密码
                    </el-dropdown-item>
                    { props.frameStore.$context.multiTenant && (
                      <el-dropdown-item command="changeTenant">
                        切换租户
                      </el-dropdown-item>
                    ) }
                    <el-dropdown-item command="userCenter">
                      个人中心
                    </el-dropdown-item>
                    <el-dropdown-item divided command="logout">
                      退出登录
                    </el-dropdown-item>
                  </el-dropdown-menu>
                );
              },
            }}
          </el-dropdown>
        </div>
      );
    };
  },
});
