import type { IEventBus } from "../../../utils/event-bus";
import type { PluginConfig, PluginInstance, PluginPosition, PluginPositionKey } from "./plugin-type";
import { markRaw, reactive } from "vue";
import { webFrameworkEvent, webFrameworkEventConfig } from "../../../utils/web-framework-event";
import { generateId } from "../layout-utils";
import { pluginPosition } from "./plugin-type";
import { PluginCustomRender } from "./render-plugins/plugin-custom-render";
import PluginIconDrawer from "./render-plugins/plugin-icon-drawer";
import PluginIconDropdown from "./render-plugins/plugin-icon-dropdown";
import PluginIconLink from "./render-plugins/plugin-icon-link";
import PluginText from "./render-plugins/plugin-text";

export class PluginManager {
  // 静态实例变量，保存唯一实例
  private static instance: PluginManager;

  readonly emitter: IEventBus = webFrameworkEvent;

  // 插件实例集合，按位置分组
  private plugins = reactive<Record<PluginPositionKey, Record<string, PluginInstance>>>({
    [pluginPosition.HEADER_LEFT]: {},
    [pluginPosition.HEADER_CENTER]: {},
    [pluginPosition.HEADER_RIGHT]: {},
    [pluginPosition.FLOATING_HELP]: {},
    [pluginPosition.SIDEBAR_LEFT]: {},
  });

  // 响应式的插件集合，供组件使用
  // public pluginsRef = readonly(this.plugins);

  // 私有构造函数，防止外部实例化
  private constructor() {}

  // 静态方法，获取唯一实例
  public static getInstance(): PluginManager {
    if (!PluginManager.instance) {
      PluginManager.instance = new PluginManager();
    }
    return PluginManager.instance;
  }

  /**
   * 注册插件
   * @param config 插件配置
   * @returns 注册是否成功
   */
  registerPlugin(config: PluginConfig): boolean {
    if (!config) {
      console.error("Plugin config cannot be null");
      return false;
    }

    // 检查插件ID是否已存在
    if (this.plugins[config.position][config.id]) {
      console.warn(`Plugin with id ${config.id} already exists in position ${config.position.toString()}`);
      return false;
    }

    if (!config.id) {
      config.id = generateId("_plugin");
    }

    // 根据插件类型创建对应的组件
    let component;
    switch (config.type) {
      case "text":
        component = PluginText;
        break;
      case "icon-dropdown":
        component = PluginIconDropdown;
        break;
      case "icon-drawer":
        component = PluginIconDrawer;
        break;
      case "icon-link":
        component = PluginIconLink;
        break;
      case "custom-render":
        component = PluginCustomRender;
        break;
      default:
        console.error(`Unsupported plugin type: ${config.type}`);
        return false;
    }

    // 创建插件实例
    const pluginInstance: PluginInstance = {
      id: config.id,
      config,
      component,
    };

    // 存储插件实例
    this.plugins[config.position][config.id] = markRaw(pluginInstance);

    // 触发插件注册事件
    webFrameworkEvent.emit(webFrameworkEventConfig.pluginRegistered, pluginInstance);

    return true;
  }

  /**
   * 移除插件
   * @param position 插件位置
   * @param id 插件ID
   * @returns 移除是否成功
   */
  removePlugin(position: PluginPositionKey, id: string): boolean {
    if (!this.plugins[position][id]) {
      console.warn(`Plugin with id ${id} not found in position ${position.description}`);
      return false;
    }

    // 保存要移除的插件实例用于事件
    const removedPlugin = this.plugins[position][id];

    // 移除插件
    delete this.plugins[position][id];

    // 触发插件移除事件
    webFrameworkEvent.emit("plugin.removed", removedPlugin);

    return true;
  }

  /**
   * 获取指定位置的所有插件
   * @param position 插件位置
   * @returns 插件实例数组
   */
  getPluginsByPosition(position: PluginPositionKey): PluginInstance[] {
    return Object.values(this.plugins[position]);
  }

  /**
   * 更新插件配置
   * @param position 插件位置
   * @param id 插件ID
   * @param newConfig 新的插件配置
   * @returns 更新是否成功
   */
  updatePluginConfig(position: PluginPosition, id: string, newConfig: Partial<PluginConfig>): boolean {
    const plugin = this.plugins[position][id];
    if (!plugin) {
      console.warn(`Plugin with id ${id} not found in position ${position}`);
      return false;
    }

    // 合并新配置
    plugin.config = { ...plugin.config, ...newConfig };

    // 触发插件更新事件
    webFrameworkEvent.emit("plugin.updated", plugin);

    return true;
  }
}

// 导出单例实例
export const pluginManager = PluginManager.getInstance();
