/**
 * 主题管理器（ThemeManager）
 * --------------------------------------------------
 * 职责：
 *  1. 维护主题注册表（内置 light/dark + 运行时注册的自定义主题）；
 *  2. 切换主题：在 <html> 上设置 data-kanban-theme 属性，并注入对应 CSS 变量；
 *  3. 持久化当前主题到 localStorage，应用启动时自动恢复；
 *  4. 提供主题列表查询、当前主题读取、light/dark 切换等能力。
 *
 * 设计要点：
 *  - 仅围绕 component-kanban/styles/variables-kanban.less 中已定义的 9 个 CSS 变量；
 *  - 内置主题（light/dark）已由 theme.less 在构建期产出静态样式，
 *    切换内置主题时只需设置 data-kanban-theme 属性即可命中对应选择器；
 *  - 自定义主题（register 注册）通过运行时注入内联 CSS 变量实现，
 *    同时也会设置 data-kanban-theme 属性，便于后续样式覆盖。
 */

import type { ThemeVars } from "./themes";
import {
  builtinThemes,
  DEFAULT_THEME,
} from "./themes";

/** localStorage 存储键 */
const STORAGE_KEY = "yq-kanban-theme";

/** data-kanban-theme 属性名 */
const DATA_THEME_ATTR = "data-kanban-theme";

class ThemeManager {
  /** 主题注册表 */
  private themes: Record<string, ThemeVars> = { ...builtinThemes };

  /** 当前主题名 */
  private currentTheme: string = DEFAULT_THEME;

  /** 主题变化监听器集合 */
  private listeners: Set<(theme: string) => void> = new Set();

  /** 是否已初始化 */
  private initialized = false;

  /**
   * 初始化主题管理器（通常在应用启动时调用一次）。
   * 会从 localStorage 恢复上次主题，并应用到 DOM。
   */
  init(theme?: string): void {
    if (this.initialized) {
      return;
    }
    this.initialized = true;

    // 优先使用传入的主题，其次读取 localStorage，最后回退默认主题
    const initialTheme
      = theme || this.readFromStorage() || DEFAULT_THEME;

    this.applyTheme(initialTheme, { persist: false });
  }

  /**
   * 注册一个自定义主题。
   * @param name  主题名（将作为 data-kanban-theme 的值）
   * @param vars  主题变量集合
   */
  register(name: string, vars: ThemeVars): void {
    this.themes[name] = vars;
  }

  /**
   * 设置当前主题。
   * @param theme 主题名（需已注册）
   */
  setTheme(theme: string): void {
    if (!this.themes[theme]) {
      console.warn(
        `[ThemeManager] 主题 "${theme}" 未注册，已注册主题：${Object.keys(
          this.themes,
        ).join(", ")}`,
      );
      return;
    }
    this.applyTheme(theme, { persist: true });
  }

  /**
   * 设置当前主题（带水波纹过渡动画）。
   * --------------------------------------------------
   * 使用 View Transitions API + clip-path circle 实现从点击位置扩散的水波纹效果。
   * 若浏览器不支持 View Transitions API，则降级为直接切换（无动画）。
   *
   * @param theme  主题名（需已注册）
   * @param event  鼠标事件（用于获取扩散起点坐标），不传则从屏幕中心扩散
   */
  setThemeWithTransition(theme: string, event?: MouseEvent): void {
    if (!this.themes[theme]) {
      console.warn(
        `[ThemeManager] 主题 "${theme}" 未注册，已注册主题：${Object.keys(
          this.themes,
        ).join(", ")}`,
      );
      return;
    }

    // 获取扩散起点坐标（默认屏幕中心）
    const x = event?.clientX ?? window.innerWidth / 2;
    const y = event?.clientY ?? window.innerHeight / 2;

    // 检测浏览器是否支持 View Transitions API（Chrome 111+ / Edge 111+）
    const doc = document as Document & {
      startViewTransition?: (cb: () => void) => {
        ready: Promise<void>;
      };
    };

    if (!doc.startViewTransition) {
      // 不支持 View Transitions API → 降级为直接切换
      this.applyTheme(theme, { persist: true });
      return;
    }

    // 启动 View Transition，在回调中执行实际的主题切换
    const transition = doc.startViewTransition(() => {
      this.applyTheme(theme, { persist: true });
    });

    // 在过渡动画就绪后，对 ::view-transition-new(root) 伪元素执行 clip-path circle 扩散
    transition.ready.then(() => {
      // 计算从点击点到视口四角的最大距离，确保圆形能完全覆盖屏幕
      const endRadius = Math.hypot(
        Math.max(x, window.innerWidth - x),
        Math.max(y, window.innerHeight - y),
      );

      document.documentElement.animate(
        {
          clipPath: [
            `circle(0px at ${x}px ${y}px)`,
            `circle(${endRadius}px at ${x}px ${y}px)`,
          ],
        },
        {
          duration: 500,
          easing: "ease-in-out",
          pseudoElement: "::view-transition-new(root)",
        },
      );
    });
  }

  /**
   * 在 light / dark 之间切换（带水波纹过渡动画）。
   * 若当前为其他主题，则切换到 light。
   *
   * @param event 鼠标事件（用于水波纹扩散起点），不传则从屏幕中心扩散
   */
  toggle(event?: MouseEvent): void {
    const next = this.currentTheme === "dark" ? "light" : "dark";
    this.setThemeWithTransition(next, event);
  }

  /**
   * 获取当前主题名。
   */
  getCurrentTheme(): string {
    return this.currentTheme;
  }

  /**
   * 获取所有已注册主题名。
   */
  getThemeList(): string[] {
    return Object.keys(this.themes);
  }

  /**
   * 判断当前是否为深色主题。
   */
  isDark(): boolean {
    return this.currentTheme === "dark";
  }

  /**
   * 订阅主题变化。
   * @returns 取消订阅函数
   */
  onChange(cb: (theme: string) => void): () => void {
    this.listeners.add(cb);
    return () => {
      this.listeners.delete(cb);
    };
  }

  // ==================== 内部方法 ====================

  /**
   * 应用主题到 DOM。
   * @param theme      主题名
   * @param options    是否持久化到 localStorage
   */
  private applyTheme(
    theme: string,
    options: { persist: boolean },
  ): void {
    const vars = this.themes[theme];
    if (!vars) {
      return;
    }

    this.currentTheme = theme;

    const root = document.documentElement;

    // 1. 设置 data-kanban-theme 属性（命中 theme.less 中的静态选择器）
    root.setAttribute(DATA_THEME_ATTR, theme);

    // 2. 注入内联 CSS 变量（确保自定义主题/无 CSS 预编译环境也能生效）
    this.injectCssVars(root, vars);

    // 3. 持久化
    if (options.persist) {
      this.writeToStorage(theme);
    }

    // 4. 通知监听器
    this.listeners.forEach(cb => cb(theme));
  }

  /**
   * 将主题变量集合注入到指定元素的 style 中。
   * 键名会被加上 `--` 前缀，例如 `yq-text-color` => `--yq-text-color`。
   */
  private injectCssVars(el: HTMLElement, vars: ThemeVars): void {
    for (const key in vars) {
      if (Object.hasOwn(vars, key)) {
        const cssVarName = key.startsWith("--") ? key : `--${key}`;
        el.style.setProperty(cssVarName, vars[key]);
      }
    }
  }

  /** 读取 localStorage */
  private readFromStorage(): string | null {
    try {
      return localStorage.getItem(STORAGE_KEY);
    } catch {
      return null;
    }
  }

  /** 写入 localStorage */
  private writeToStorage(theme: string): void {
    try {
      localStorage.setItem(STORAGE_KEY, theme);
    } catch {
      // 忽略写入失败（如隐私模式）
    }
  }
}

/** 全局唯一的主题管理器实例 */
export const themeManager = new ThemeManager();

/**
 * 模块加载时自动初始化主题（从 localStorage 恢复上次主题）。
 * --------------------------------------------------
 * 只要此模块被 import（直接或间接），就会自动执行初始化，
 * 确保页面刷新后主题状态能正确恢复，无需手动调用 initTheme()。
 *
 * SSR 安全：仅在浏览器环境（document 存在）时执行。
 */
if (typeof document !== "undefined") {
  themeManager.init();
}

export { DATA_THEME_ATTR, STORAGE_KEY };
