import type { Component } from "vue";
import type { RouteLocationRaw } from "vue-router";
import { computed, defineComponent } from "vue";
import { useCsNamespace } from "../../hooks/use-namespace";
import { urlUtil } from "../../utils";
import "./layout-navigation-style.less";

export interface INavigationItemType {
  /**
	 * 菜单项标题
	 */
  title: string;

  /**
	 * @description 路由跳转目标，同 vue-router 的 to 属性
	 */
  to?: RouteLocationRaw;

  /**
	 * @description 如果设置该属性为 true, 导航将不会留下历史记录
	 */
  replace?: boolean;
}

/**
 * @description 布局导航
 * @example
 *                 <LayoutNavigation
 *                   routers={[{ title: "测试", to: "/test" }, { title: "测试2", to: "/test2" }]}
 *                 >
 *                   <el-button type="primary" text>关闭</el-button>
 *                   <el-button type="primary" text>关闭2</el-button>
 *                 </LayoutNavigation>
 */
export const LayoutNavigation = defineComponent({
  name: "LayoutNavigation",
  props: {
    routers: {
      type: Array as () => INavigationItemType[],
      required: false,
    },
    /**
		 * @description separator character
		 */
    separator: {
      type: String,
      default: "/",
    },
    /**
		 * @description icon component of icon separator
		 */
    separatorIcon: {
      type: Object as () => Component,
    },
  },
  setup(props, { slots }) {
    const { searchParams } = urlUtil.extractUrlParams<{ menuName: string }>(location.href);
    const ns = useCsNamespace("layout-navigation");

    const breadcrumbItems = computed(() => {
      const menuName = searchParams?.menuName || "页面";

      // 导航路径只展示当前模块下操作路径
      const items: INavigationItemType[] = [{
        title: menuName,
        to: "/",
      }];

      if (props.routers) {
        items.push(...props.routers);
      }

      return items;
    });

    return () => {
      return (
        <div class={ns.b()}>
          <el-breadcrumb
            separator={props.separator}
            separator-icon={props.separatorIcon}
            class={ns.e("breadcrumb")}
          >
            { breadcrumbItems.value.map((item) => {
              if (item.to) {
                return <el-breadcrumb-item to={item.to}>{ item.title }</el-breadcrumb-item>;
              }
              return <el-breadcrumb-item>{ item.title }</el-breadcrumb-item>;
            }) }
          </el-breadcrumb>
          <div class={ns.e("tool")}>
            { slots.default?.() }
          </div>
        </div>
      );
    };
  },
});
