/**
 * 解析查询字符串为对象（支持重复键、URL解码、空值处理）
 * @param queryString 查询字符串（如 "a=1&b=2" 或 "?a=1&b=2"）
 * @returns 解析后的参数对象，值为字符串或字符串数组（重复键场景）
 */
function parseQueryString<T = Record<string, string | string[]>>(queryString: string): T {
  const params = {} as T;
  if (!queryString) {
    return params;
  }

  // 移除开头的问号（存在时）
  const cleanStr = queryString.startsWith("?") ? queryString.slice(1) : queryString;
  if (!cleanStr) {
    return params;
  }

  // 分割参数对（处理连续&的空值场景）
  const pairs = cleanStr.split("&").filter(pair => pair.length > 0);

  for (const pair of pairs) {
    const equalsIndex = pair.indexOf("=");
    let key: string;
    let value: string;

    if (equalsIndex === -1) {
      // 无值参数（如 ?a&b=1 中的 a）
      key = decodeURIComponent(pair);
      value = "";
    } else {
      // 分割键值对（支持值中包含=）
      key = decodeURIComponent(pair.slice(0, equalsIndex));
      value = decodeURIComponent(pair.slice(equalsIndex + 1));
    }

    // 处理重复键（转为数组）
    if (Object.hasOwn(params as Record<string, unknown>, key)) {
      const existing = params[key];
      params[key] = Array.isArray(existing) ? [...existing, value] : [existing, value];
    } else {
      params[key] = value;
    }
  }

  return params;
}

/**
 * 从URL中提取 search参数、hash参数、hashname
 * @param url 完整的URL字符串
 * @returns 提取结果对象
 *   - searchParams: ?后面的查询参数对象
 *   - hashParams: #后面?部分的查询参数对象
 *   - hashname: #后面?之前的路径部分（如 #/detail?a=1 中的 "/detail"）
 */
function extractUrlParams<T = Record<string, string | string[]>,	U = Record<string, string | string[]>>(url: string): { searchParams: T; hashParams: U; hashname: string } {
  // 初始化默认返回值
  const result = {
    searchParams: {} as T,
    hashParams: {} as U,
    hashname: "",
  };

  // 处理无效输入（非字符串或空字符串）
  if (typeof url !== "string" || url.trim() === "") {
    return result;
  }

  // 1. 分割 URL 为 非hash部分 和 hash部分（#及后面内容）
  const hashSplitIndex = url.indexOf("#");
  const [urlWithoutHash, hashFullStr] = hashSplitIndex === -1
    ? [url, ""]
    : [url.slice(0, hashSplitIndex), url.slice(hashSplitIndex + 1)];

  // 2. 解析 search 参数（?及后面内容）
  const searchSplitIndex = urlWithoutHash.indexOf("?");
  const searchStr = searchSplitIndex === -1 ? "" : urlWithoutHash.slice(searchSplitIndex + 1);
  result.searchParams = parseQueryString(searchStr);

  // 3. 解析 hashname 和 hashParams（hash中?前后部分）
  const hashQuerySplitIndex = hashFullStr.indexOf("?");
  if (hashQuerySplitIndex === -1) {
    // hash中无查询参数（如 #/detail）
    result.hashname = hashFullStr;
    result.hashParams = {} as any;
  } else {
    // hash中有查询参数（如 #/detail?a=1&b=2）
    result.hashname = hashFullStr.slice(0, hashQuerySplitIndex);
    const hashQueryStr = hashFullStr.slice(hashQuerySplitIndex + 1);
    result.hashParams = parseQueryString(hashQueryStr);
  }

  return result;
}

/**
 * 超简化版 stringify：仅处理一层结构对象，支持基础类型和数组，无配置参数
 * - 只处理一层键值对，不支持嵌套对象
 * - 支持基础类型（字符串/数字/布尔值）和一维数组
 * - 自动对键值进行 URL 编码
 * - 跳过 null/undefined 值
 * @param obj 要序列化的一层结构对象
 * @returns 序列化后的查询字符串
 */
function stringify(obj: Record<string, unknown>): string {
  // 非对象输入直接返回空字符串
  if (typeof obj !== "object" || obj === null) {
    return "";
  }

  const pairs: string[] = [];

  Object.entries(obj).forEach(([key, value]) => {
    // 跳过 null/undefined
    if (value === null || value === undefined) {
      return;
    }

    // 处理数组（格式：key[]=val1&key[]=val2）
    if (Array.isArray(value)) {
      value.forEach((item) => {
        // 跳过数组中的 null/undefined
        if (item === null || item === undefined) {
          return;
        }
        const encodedKey = encodeURIComponent(key);
        const encodedValue = encodeURIComponent(String(item));
        pairs.push(`${encodedKey}[]=${encodedValue}`);
      });
      return;
    }

    // 处理基础类型（转为字符串后编码）
    const encodedKey = encodeURIComponent(key);
    const encodedValue = encodeURIComponent(String(value));
    pairs.push(`${encodedKey}=${encodedValue}`);
  });

  return pairs.join("&");
}

export const urlUtil = {
  parseQueryString,
  extractUrlParams,
  stringify,
};
