/**
 * iframe通信桥接协议类型定义
 * @fileoverview 定义父子应用之间 postMessage 通信的消息格式
 */

// ============================================================================
// 消息类型常量
// ============================================================================

/** Portal 通信消息类型 */
export const PortalMessageType = {
  /** 子→父: 打开新Tab页签 */
  OPEN_TAB: "portal:openTab",
  /** 子→父: 关闭Tab页签 */
  CLOSE_TAB: "portal:closeTab",
  /** 子→父: 设置编辑状态 */
  SET_EDITING: "portal:setEditing",
  /** 子→父: 弹出Message提示 */
  SHOW_MESSAGE: "portal:showMessage",
  /** 父→子: 关闭前确认（已有协议，保持兼容） */
  BEFORE_CLOSE: "tab:beforeClose",
  /** 子→父: 关闭前确认响应（已有协议，保持兼容） */
  BEFORE_CLOSE_RESPONSE: "tab:beforeClose:response",
  /** 父→子: Tab激活（已有协议，保持兼容） */
  TAB_ACTIVATE: "tab:activate",
  /** 父→子: Tab停用（已有协议，保持兼容） */
  TAB_DEACTIVATE: "tab:deactivate",
  /** 父→子: Tab卸载（已有协议，保持兼容） */
  TAB_UNMOUNT: "tab:unmount",
  /** 子→父: 请求获取上下文数据 */
  GET_CONTEXT: "portal:getContext",
  /** 父→子: 返回上下文数据 */
  GET_CONTEXT_RESPONSE: "portal:getContext:response",
  /** 子→父: 重定向至登录页 */
  REDIRECT_LOGIN: "portal:redirectLogin",
} as const;

// ============================================================================
// 消息信封（统一格式）
// ============================================================================

/** 消息信封接口 - 所有 postMessage 通信使用此格式 */
export interface PortalMessage<T = any> {
  /** 消息类型 */
  type: string;
  /** 业务数据 */
  data: T;
  /** 消息来源标识 */
  source: "main-app" | "child-app";
  /** 时间戳 */
  timestamp: number;
}

// ============================================================================
// 各消息的业务数据类型
// ============================================================================

/** 打开Tab的参数 */
export interface OpenTabData {
  menuId: string;
  menuName: string;
  moduleId: string;
  moduleUrl: string;
  applicationId: string;
  applicationName: string;
  /** 是否可关闭，默认true */
  closable?: boolean;
  /** 其他扩展字段 */
  [key: string]: any;
}

/** 设置编辑状态的参数 */
export interface SetEditingData {
  tabId: string;
  isEditing: boolean;
  data?: Record<string, any>;
}

/** 弹出Message的参数 */
export interface ShowMessageData {
  type: "success" | "warning" | "info" | "error";
  message: string;
  duration?: number;
}

/** 关闭Tab的参数 */
export interface CloseTabData {
  /** 要关闭的Tab ID，不传则关闭当前Tab（自身） */
  tabId?: string;
  /** 是否强制关闭（忽略编辑状态），默认 false */
  force?: boolean;
}

/** 关闭前确认请求数据 */
export interface BeforeCloseData {
  tabId: string;
}

/** 关闭前确认响应数据 */
export interface BeforeCloseResponseData {
  tabId: string;
  allow: boolean;
  message?: string;
}

/** 重定向至登录页的参数 */
export interface RedirectLoginData {
  /** 登录页地址，不传则由父应用使用默认登录页地址 */
  loginUrl?: string;
  /** 重定向原因说明（可选，用于日志记录） */
  reason?: string;
}

/** 获取上下文数据的请求参数 */
export interface GetContextRequestData {
  /** 发起请求的 tabId */
  tabId: string;
}

/** 获取上下文数据的响应数据（镜像 portalStore.$context / IPublicContextStateType） */
export interface GetContextResponseData {
  /** 门户Logo */
  portalLogo: string;
  /** 门户名称 */
  portalName: string;
  /** 应用图标 */
  appIcon: string;
  /** 应用名称 */
  appName: string;
  /** 应用ID */
  applicationId: string;
  /** 组织ID */
  orgId: string;
  /** 组织简称 */
  orgShortName: string;
  /** 组织类型 */
  orgType: string;
  /** 扩展类型 */
  extType: string;
  /** 父级ID */
  parentId: string;
  /** 权限列表 */
  permissions: string[];
  /** 产品编码 */
  productCode: string;
  /** 产品名称 */
  productName: string;
  /** 产品列表 */
  products: Array<{ code: string; name: string; [key: string]: any }>;
  /** 手机号 */
  phoneNumber: string;
  /** 用户ID */
  userId: string;
  /** 用户头像URL */
  userAvatarUrl: string;
  /** 用户名 */
  userName: string;
  /** 真实姓名 */
  realName: string;
  /** 租户ID */
  tenantId: number;
  /** 租户编码 */
  tenantCode: string;
  /** 租户名称 */
  tenantName: string;
  /** 是否内部用户 */
  internalUser: boolean;
  /** 是否启用工作台应用 */
  workstationApp: boolean;
  /** 完整ID路径 */
  fullId: string;
  /** 组织名称 */
  orgName: string;
  /** 组织全称 */
  orgFullName: string;
  /** 模块ID */
  moduleId: string;
  /** 模块名称 */
  moduleName: string;
  /** 模块URL */
  moduleUrl: string;
  /** 模块编码 */
  moduleCode: string;
}

// ============================================================================
// PortalBridge 配置
// ============================================================================

/** PortalBridge 初始化配置 */
export interface PortalBridgeOptions {
  /** 当前Tab的menuId，不传则尝试从URL参数获取 */
  tabId?: string;
  /** 是否开启调试日志 */
  debug?: boolean;
}
