import { defineComponent, inject, PropType } from "vue";
import { TreeNode } from "./type";

interface SelectSlots {
  listitem?: (data: { row: Record<string, any> }) => void;
  treeitem?: (data: { row: Record<string, any> }) => void;
}

// 带render函数的组件 优点：可将逻辑区与模版区分开
export const RenderRow = defineComponent({
  name: "RenderRow",
  inheritAttrs: true,
  props: {
    data: {
      type: Object as PropType<TreeNode>, // 泛型类型
      required: true,
    },
    name: {
      type: String, // 泛型类型
      required: true,
    },
  },
  setup(props) {
    const selectSlots: SelectSlots = inject("selectSlots") ?? {};
    return () => {
      if (props.name === "listitem" && selectSlots.listitem) {
        return (
          <>
            {selectSlots?.listitem({ row: props.data })}
          </>
        );
      }
      if (props.name === "treeitem" && selectSlots?.treeitem) {
        return (
          <span class="yq-item-title-text">
            {selectSlots?.treeitem({ row: props.data })}
          </span>
        );
      }
    };
  },
});
