import type { PropType } from "vue";
import type { CustomRenderPluginConfig } from "../plugin-type";
import { defineComponent, h } from "vue";

export const PluginCustomRender = defineComponent({
  name: "PluginCustomRender",
  props: {
    config: {
      type: Object as PropType<CustomRenderPluginConfig>,
      required: true,
    },
  },
  setup(props) {
    if (!props.config || !props.config.renderComponent) {
      console.error(`PluginCustomRender: config is null or undefined.`, props.config);
      return null;
    }
    return () => {
      return (
        <div class="layout-plugin-custom-render">
          {h(props.config.renderComponent)}
        </div>
      );
    };
  },
});
