import type { PropType } from "vue";
import type { IconDrawerPluginConfig } from "../plugin-type";
import { ElTooltip } from "element-plus";
import { defineComponent, h, reactive } from "vue";
import { webFrameworkEvent } from "../../../../utils/web-framework-event";

export default defineComponent({
  name: "PluginIconDrawer",
  props: {
    config: {
      type: Object as PropType<IconDrawerPluginConfig>,
      required: true,
    },
  },
  setup(props) {
    const state = reactive({
      visible: false,
    });

    const methods = {
      openDrawer: () => {
        state.visible = true;
        webFrameworkEvent.emit(`plugin.${props.config.id}.drawer.open`);
      },
      closeDrawer: () => {
        state.visible = false;
        webFrameworkEvent.emit(`plugin.${props.config.id}.drawer.close`);
      },
      renderIcon: () => {
        if (!props.config.tooltip) {
          return (
            <span
              class="layout-plugin-icon-link-wrapper"
              onClick={methods.openDrawer}
            >
              {h(props.config.icon)}
            </span>
          );
        }
        return (
          <ElTooltip
            effect="dark"
            content={props.config.tooltip || ""}
            placement={props.config.placement || "top"}
          >
            {{
              default: () => {
                return (
                  <span
                    class="layout-plugin-icon-link-wrapper"
                    onClick={methods.openDrawer}
                  >
                    {h(props.config.icon)}
                  </span>
                );
              },
            }}
          </ElTooltip>
        );
      },
    };
    return () => {
      return (
        <div class={["layout-portal-plugin-icon-drawer", props.config.id]}>
          {methods.renderIcon()}
          <el-drawer
            v-model={state.visible}
            title={props.config.title}
            size={props.config.width || 300}
            direction={props.config.direction || "rtl"}
            destroy-on-close={true}
            beforeClose={() => {
              state.visible = false;
            }}
            append-to-body={true}
            append-to="body"
            onClose={methods.closeDrawer}
          >
            {h(props.config.component)}
          </el-drawer>
        </div>
      );
    };
  },
});
