import { computed, defineComponent, ref, watch } from "vue";
import { $http } from "../../index-kanban";
import { IPublicFramePortalType } from "../../types";

export const TenantLogoWidget = defineComponent({
  name: "TenantLogoWidget",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(props) {
    const tenantLogSrc = ref("");
    const title = computed(() => {
      return `${props.frameStore.$context.tenantName}／${props.frameStore.$context.appName}`;
    });
    watch(() => props.frameStore.$context.portalLogo, (portalLogo) => {
      const params = {
        key: portalLogo, // oss文件唯一标识数组
        options: {
          // isPublic: true,
        },
      };
      if (portalLogo) {
        $http.post("/pmShare/file/signatureUrl", params).then((res) => {
          if (res.result) {
            tenantLogSrc.value = res.result;
          }
        }).catch((err) => {
          console.error(err);
        });
      }
    }, {
      immediate: true,
    });
    return () => {
      return (
        <div title={title.value}>
          <img
            style={{ width: "40px", height: "40px" }}
            src={tenantLogSrc.value}
            alt=""
          />
        </div>
      );
    };
  },
});
