export function nodeIconClass(extType) {
  let cls = "cs ";
  switch (extType) {
    case "group":
      cls += "jituan";
      break;
    case "company":
      cls += "gongsi";
      break;
    case "specialized":
      cls += "zhuanyegongsi";
      break;
    case "department":
      cls += "bumen";
      break;
    case "folder":
      cls += "fenzu";
      break;
    case "command":
      cls += "zhihuibu";
      break;
    case "project":
      cls += "xiangmubu";
      break;
    case "production":
      cls += "shengchanzuzhi";
      break;
    default:
      cls += "xiangmubu";
      break;
  }
  return cls;
}
