<template>
  <ul
    v-if="props.listData.length > 0"
    class="search-list"
  >
    <li
      v-for="(item, i) in props.listData"
      :key="i"
      class="search-list-item"
      :class="{ 'yq-item-title-disabled': item[disabledProp] }"
      @click.stop="_selectRow(item)"
    >
      <RenderRow v-if="selectSlots.listitem" :data="item" name="listitem" />
      <template v-else>
        <p class="label">
          {{ item[labelProp] }}
        </p>
      </template>
    </li>
  </ul>
  <p v-if="props.listData.length === 0 && !props.loading" class="search-select_loading">
    <el-empty description="暂无搜索结果" :image-size="60" />
  </p>
  <p v-if="props.loading" class="search-select_loading">
    数据加载中...
  </p>
</template>

<script lang="ts" setup>
import { inject } from "vue";
import { RenderRow } from "./render-row";
import { DefaultProps, TreeNode } from "./type";

export interface Props {
  listData: TreeNode[];
  loading: boolean;
}
interface SelectSlots {
  listitem?: object;
}
interface selectRowFunc {
  (node: TreeNode): void;
}
const props = withDefaults(defineProps<Props>(), {
  listData: () => [],
  loading: false,
});
const defaultProps: DefaultProps = inject("defaultProps") || {};
const selectSlots: SelectSlots = inject("selectSlots") || {};

const labelProp = defaultProps.label || "";
const disabledProp = defaultProps.disabled || "";

const selectRow: selectRowFunc | undefined = inject("selectRow");
function _selectRow(item: TreeNode) {
  if (selectRow && !item[disabledProp]) {
    selectRow(item);
  }
}
</script>
