/**
 * 主题预设定义
 * --------------------------------------------------
 * 严格基于 component-kanban/styles/variables-kanban.less 中已定义的 CSS 变量，
 * 不引入任何新的颜色变量。仅围绕现有 9 个变量提供 light / dark 预设。
 *
 * 与 theme.less 的关系：
 *  - theme.less 在构建期产出 :root / [data-kanban-theme="light"] / [data-kanban-theme="dark"] 的静态样式；
 *  - 本文件在运行期提供同样的变量集合，便于：
 *      1) 在无 CSS 预编译的环境（如 iframe、动态注入）应用主题；
 *      2) 注册自定义主题（用户/租户自定义配色）；
 *      3) 与 localStorage 配合做主题持久化恢复。
 *
 * 注意：保持本文件与 theme.less 中的变量值一致，避免运行时与构建期不一致。
 */

/** 现有 CSS 变量键名（与 variables-kanban.less 保持一致） */
export type ThemeVarKey
  = | "yq-text-color"
    | "yq-header-background-color"
    | "yq-widget-hover-text-color"
    | "yq-widget-hover-background-color"
    | "yq-header-height"
    | "yq-light-header-bg-color"
    | "yq-light-header-text-color"
    | "yq-light-header-link-text-color"
    | "yq-content-bg-color";

/** 单个主题的变量集合 */
export type ThemeVars = Partial<Record<ThemeVarKey, string>> & Record<string, string>;

/** 浅色（默认）主题 */
export const lightTheme: ThemeVars = {
  /* 文字颜色 */
  "yq-text-color": "#303133",
  /* 背景颜色 */
  "yq-header-background-color": "#FFFFFF",
  /* 小部件悬停文字颜色 */
  "yq-widget-hover-text-color": "#FFFFFF",
  /* 小部件悬停背景颜色 */
  "yq-widget-hover-background-color": "#FFFFFF",
  /* 头部高度 */
  "yq-header-height": "60px",
  /* 头部背景色 */
  "yq-light-header-bg-color": "var(--el-color-primary)",
  /* 头部文字颜色 */
  "yq-light-header-text-color": "#303133",
  /* 顶部导航 */
  "yq-light-header-link-text-color": "#ffffff",
  /* 页面背景色 */
  "yq-content-bg-color": "#F0F8FF",
};

/** 深色主题 */
export const darkTheme: ThemeVars = {
  /* 文字颜色 */
  "yq-text-color": "#E5EAF3",
  /* 头部背景颜色 */
  "yq-header-background-color": "#1D1E1F",
  /* 页面背景色 */
  "yq-content-bg-color": "#12131a",

  /* 小部件悬停文字颜色 */
  "yq-widget-hover-text-color": "#E5EAF3",
  /* 小部件悬停背景颜色 */
  "yq-widget-hover-background-color": "#2A2B2C",
  /* 头部高度（保持不变） */
  "yq-header-height": "60px",
  /* 头部背景色 */
  "yq-light-header-bg-color": "#1D1E1F",
  /* 头部文字颜色 */
  "yq-light-header-text-color": "#E5EAF3",
  /* 顶部导航 */
  "yq-light-header-link-text-color": "#E5EAF3",
};

/** 内置主题注册表 */
export const builtinThemes: Record<string, ThemeVars> = {
  light: lightTheme,
  dark: darkTheme,
};

/** 默认主题名 */
export const DEFAULT_THEME = "light";
