import { $http } from "../utils/request";

/**
 * api-custom-config
 * 自定义配置接口
 */
export const apiCustomConfig = {
  /**
	 * 用户获取自定义配置信息（表格、表单、过滤器、信息面板）
	 * @param params
	 */
  getModuleCustomConfig: <T = any>(params: Record<string, any>) => {
    return $http.post<T>("/bmShare/bm-customized-api/get-module-custom-config", params);
  },

  /**
	 * 获取用户自定义配置信息（打印、导出）
	 * @param params
	 */
  getExportConfig: <T = any>(params: Record<string, any>) => {
    return $http.post<T>("/bmShare/bm-customized-api/get-export-config", params);
  },

  /**
	 * 用户获取控制自定义配置面板是否显示
	 * @param params
	 */
  getCustomPanel: <T = any>(params: Record<string, any>) => {
    return $http.post<T>("/bmShare/bm-customized-api/get-custom-panel", params);
  },

  /**
	 * 打印——获取配置面板打印配置code项
	 * @param params
	 */
  /* printConfigItems: <T = any>(params: Record<string, any>) => {
		return $http.get<T>("/bmShare/bm-customized-api/print-config-items", { params });
	}, */
};
