import { ref, Ref } from "vue";
import { DefaultProps, TreeNode } from "./type";

interface LoadTreeType {
  loadDefaultNodes: (treeData, level, parentNode) => void;
  defaultExpandedKeys: Ref<string[] | number[]>;
}
interface loadTreeParams {
  defaultProps: DefaultProps;
  moreEnable: boolean;
  currentSize: number;
  defaultExpandLastNode: boolean;
}
export function useLoadTreeFunc(emits, {
  defaultProps,
  moreEnable,
  currentSize,
  defaultExpandLastNode,
}: loadTreeParams, resetPopoverHeight): LoadTreeType {
  const defaultExpandedKeys: Ref<string[]> = ref([]);
  const loadDefaultNodes = (treeData, level, parentNode): void => {
    const currentValue = defaultExpandedKeys.value[level - 1]; // 比较时将id转换为string，防止数据类型不一致

    if (!currentValue) {
      return;
    }
    const parentValue = parentNode[defaultProps.value as keyof typeof parentNode];
    if (level > 1 && currentValue === parentValue) {
      console.warn("[ElementPro]:<search-tree> 子父节点相同，自动展开已退出");
      return;
    }
    const currentNode = treeData.filter(item => currentValue === item[defaultProps.value as keyof typeof item]);
    // 如果已经查到当前节点，就直接加载下一级
    if (currentNode.length > 0) {
      // 最后一级时判断是否需要展开该节点
      if (level !== 1 && level === defaultExpandedKeys.value.length && !defaultExpandLastNode) {
        return;
      }
      if (level <= defaultExpandedKeys.value.length) {
        expand(currentNode[0], level, parentNode);
      }
    } else {
      // 如果没有查到节点，则需要加载更多
      if (parentNode && moreEnable) {
        expandMore(parentNode, level - 1);
      }
    }
  };
  const expand = (node: TreeNode, level: number, parentNode): void => {
    if (node.loaded) {
      node.expanded = true;
      if (level < defaultExpandedKeys.value.length) {
        loadDefaultNodes(node.children, level + 1, parentNode);
      }
      return;
    }
    node.loading = true;
    if (!node.children) {
      node.children = [];
    }
    node.limit = currentSize + 1;
    node.offset = 0;
    emits("loadNode", node, (arr: TreeNode[]) => {
      if (arr.length > currentSize && moreEnable) {
        node.hasMore = true;
        node.children = arr.slice(0, arr.length - 1);
      } else {
        node.children = arr;
      }
      node.loading = false;
      node.expanded = true;
      node.loaded = true;
      if (resetPopoverHeight) {
        resetPopoverHeight();
      }
      if (level < defaultExpandedKeys.value.length) {
        loadDefaultNodes(node.children, level + 1, node);
      }
    });
  };
  const expandMore = (node: TreeNode, level: number): void => {
    // 回调函数中处理数据
    if (!node.offset) {
      node.offset = 0;
    }
    node.offset += currentSize;
    node.moreLoading = true;
    emits("loadNode", node, (arr: TreeNode[]) => {
      node.moreLoading = false;
      if (!arr.length || arr.length === 0) {
        return;
      }
      if (!node.children) {
        node.children = [];
      }
      if (arr.length <= currentSize) {
        node.hasMore = false;
        node.children.push(...arr);
      } else {
        node.children.push(...arr.slice(0, arr.length - 1));
      }
      if (resetPopoverHeight) {
        resetPopoverHeight();
      }
      loadDefaultNodes(node.children, level + 1, node);
    });
  };
  return {
    loadDefaultNodes,
    defaultExpandedKeys,
  };
}
