/**
 * 从父级获取指定上下文数据
 * @type {string[]}
 */
const PARENT_CONTEXT_KEY = [
  // 租户信息
  "tenantId",
  "tenantCode",
  "tenantName",

  // 组织信息
  "userId",
  "userName",
  "realName",
  "loginId",
  "phoneNumber",
  "eMail",

  // 组织信息
  "orgId",
  "orgName",
  "orgShortName",
  "orgType",
  "extType",

  "fullId",
  "orgFullName",
  "orgType",
  "extType",
  "parentId",

  // 其他
  "multiTenant",
  "products",

  /* 租户logo */
  "portalLogo",

  /* 多租户标识 */
  "multiTenant",
];

const durationTime = 10 * 1000;

export async function initWebContext(): Promise<boolean> {
  const parserQuery = urlUtil.extractUrlParams<QueryParamsType, any>(location.href);
  let queryParams = parserQuery.searchParams; // getUrlParameters<QueryParamsType>();
  const frameStore = portalStore();
  // 自定义应用和查询元数据
  if (customConfigManagerPlugin.queryParams) {
    queryParams = customConfigManagerPlugin.queryParams;
  }
  const formatParams = formatQueryParams(queryParams);

  if (!queryParams || !queryParams.applicationId) {
    ElMessage.info({
      message: "访问参数不完整",
      duration: durationTime,
    });
    return Promise.resolve(false);
  }

  frameStore.setQueryParams(queryParams);
  const params = {
    params: {
      applicationId: formatParams.params.applicationId,
      moduleId: formatParams.params.moduleId!,
      orgId: formatParams.params.orgId!,
    },
    headers: {
      // "X-tenant-id": queryParams.tenantId,
    },
  };

  const portalResult = await apiPortal.portalInit(params);
  if (!portalResult) {
    ElMessage.error("获取上下文错误");
    return Promise.resolve(false);
  }

  debugger;
  return new Promise((resolve) => {
    apiPortal.initContext(params)
      .then((res: any) => {
        if (!res.result) {
          ElMessage.error("获取上下文错误");
          resolve(false);
        }
        const parentCtx = portalResult.result;
        if (!parentCtx || !parentCtx.tenantId) {
          ElMessage.error("获取父级上下文错误");
          throw new Error("获取父级上下文错误");
          return;
        }
        const parentCtxData = pick(parentCtx, PARENT_CONTEXT_KEY);
        const result = Object.assign(parentCtxData, res.result);

        // url orgId moduleId moduleUrl 不一致就需要重新跳转
        if (result.moduleUrl !== formatParams.pathname
          || ((formatParams.params.moduleId) && formatParams.params.moduleId !== result.moduleId)
          || ((formatParams.params.orgId) && formatParams.params.orgId !== result.orgId)
          || (!queryParams.orgId || !queryParams.moduleId)) {
          // 发布错误提示，模块没有权限访问
          webFrameworkEvent.emit(webFrameworkEventConfig.noPagePermission, {
            data: {
              message: "暂无权限，请联系管理员授权后重试",
            },
          });
          return false;
          const newHref = redirectUrl({
            url: result.moduleUrl,
            applicationId: result.applicationId,
            moduleId: result.moduleId,
            orgId: result.orgId,
          });

          if (!customConfigManagerPlugin.queryParams) {
            window.location.href = newHref;
            return false;
          }
        }

        frameStore.setContext(result);

        $http.setHeaders({
          "x-client-ajax": true,
          "x-org-id": result.orgId ?? "",
          // "x-user-name": encrypt(result.userName) || "",
          // "x-batch-id": result.batchId ?? "",
          "x-application-id": result.applicationId ?? "",
          // "x-tenant-id": result.tenantId ?? "",
          // "x-tenant-code": result.tenantCode ?? "",
        });

        // 上下文接口初始化完成
        webFrameworkEvent.emit(webFrameworkEventConfig.initContext, result);

        // queryUserApplications();

        // 获取菜单
        // await Promise.allSettled([initMenu(result), queryOrgNode({ parentId: "-1", key: "" })]);
        // await initMenu(result);
        resolve(true);
        afterSaveHistory(result);
      })
      .catch((error) => {
        console.log(error);
        // 参数错误
        if (error?.response?.status === 400) {
          ElMessage.error({
            message: error.response.data.message,
            duration: durationTime,
          });

          // 发布错误提示
          webFrameworkEvent.emit(webFrameworkEventConfig.portalWarning, {
            data: {
              message: error.response.data.message,
            },
          });
        } else if (error.code === "ERR_NETWORK") {
          ElMessage.error("请求网络超时");
        } else {
          ElMessage.error({
            message: "获取上下文错误",
            duration: durationTime,
          });
        }
        resolve(false);
      });
  });
}

export async function initKanbanPortal(): Promise<boolean> {
  return await initWebContext();
}

