/**
 * 创建访问历史记录
 * @param {Record<string, any>} params
 */
export function createHistory(params: Record<string, any>) {
  // 通过菜单入口不记录访问历史
  if (params?.moduleUrl?.includes("entrypoint.html") || params?.moduleUrl?.includes("work-station.html")) {
    return;
  }
  apiPortal.accessHistory(params).then(() => {
    // pass
  }).catch((error) => {
    console.log(error);
  });
}

/**
 * 保存访问历史记录
 * @param {{appIcon: string, appName: string, applicationId: string, extType: string, fullId: string, internalUser: boolean, moduleCode: string, moduleId: string, moduleName: string, moduleUrl: string, orgFullName: string, orgId: number, orgName: string, orgShortName: string, orgType: string, parentId: number, permissions: string[], phoneNumber: string, portalLogo: string, portalName: string, productCode: string, productId: string, productName: string, products: {id: string, name: string, productLineName: string}[], realName: string, tenantCode: string, tenantId: number, tenantName: string, userAvatarUrl: string, userId: string, userName: string, workstationApp: boolean}} context
 */
function afterSaveHistory(context: IPublicContextStateType) {
  const frameStore = portalStore();

  const { searchParams } = urlUtil.extractUrlParams(location.href);
  if (!searchParams || !searchParams.menuId) {
    console.warn("菜单id解析失败，不报错访问记录");
    return;
  }

  const menuName = (searchParams.menuName || context.moduleName) as string;
  // const decodeMenuName = decodeURIComponent(menuName);
  const historyParams = {
    menuId: searchParams.menuId,
    menuName,
    // moduleId: frameStore.$context.moduleId,
    // moduleName: "移动工作台",
    // moduleCode: "mobile-portal",
    ...pick(frameStore.$context, ["moduleId", "moduleName", "moduleCode", "applicationId"]),
    moduleUrl: context.moduleUrl,
    productId: context.productId,
    productName: context.productName,
    productCode: context.productCode,
    // applicationId: "9995000019421184",
    applicationName: frameStore.$context.appName,
    applicationIcon: frameStore.$context.appIcon,
    loginType: "web",
    loginWay: "账号密码",
  };
  if (!historyParams.menuId || !historyParams.menuName || !historyParams.moduleId || !historyParams.applicationId) {
    return;
  }
  createHistory(historyParams);
}
