import type { App } from "vue";
import type { PluginManager } from "./plugins/layout-plugin/plugin-manage/plugin-manager";
import type { LayoutFrameworkOptions } from "./types";
import ElementPlus from "element-plus";
import { createPinia } from "pinia";
import { createApp, h, markRaw } from "vue";
import { KanbanSetting } from "./component-kanban/kaban-widget/kaban-setting/kanban-setting";
import { KanbanLayoutContainer } from "./component-kanban/kanban-layout-container/kanban-layout-container";
import { TenantOrgWidget } from "./components/common-widget";
import { ApplicationNameWidget } from "./components/common-widget/application-name-widget/application-name-widget";
import { AccountManagement } from "./components/common-widget/right-account-management/account-management";
import { TenantLogoWidget } from "./components/common-widget/tenant-logo-widget";
import { FloatingHelpFeedback } from "./components/widget/floating-help/feedback/floating-help-feedback";
import { FloatingDocument } from "./components/widget/floating-help/floating-document";
import { FloatingSystemMessage } from "./components/widget/floating-help/floating-system-message";
import { pluginManager } from "./plugins";
import { ThemeTypeValue } from "./plugins/layout-plugin";
import { pluginPosition, PluginType } from "./plugins/layout-plugin/plugin-manage/plugin-type";
import { portalStore } from "./stores";
import { zhCnDefault } from "./utils/zh-cn";

export class KanbanWebFramework {
  private mountPoint: string | HTMLElement;
  private options: LayoutFrameworkOptions;
  private initialized: boolean = false;

  // 插件管理器 - 使用单例实例
  public pluginManager: PluginManager;

  constructor(options: LayoutFrameworkOptions) {
    // 设置默认配置
    this.options = {
      el: "#app",
      ...options,
    };

    this.options = { theme: ThemeTypeValue.LIGHT, ...this.options };

    // 验证必要参数
    if (!this.options.bodyComponent) {
      console.warn("LayoutFramework requires a Vue bodyComponent in options");
    }
    this.mountPoint = this.options.el!;

    this.pluginManager = pluginManager;
    // 初始化应用
    this.initApp();
  }

  // 初始化Vue应用
  private async initApp(): Promise<void> {
    if (this.initialized) {
      console.warn("LayoutFramework has already been initialized");
      return;
    }

    const app = createApp(KanbanLayoutContainer, {
      pluginManager: this.pluginManager,
      rootComponent: markRaw(this.options.bodyComponent),
    });

    // 注入外来配置
    Object.assign(app.config, {
      bodyComponent: markRaw(this.options.bodyComponent), // 外部挂载点
      frameLayoutConfig: this.options.frameConfig,
    });

    app.use(createPinia());

    // 注册基础、扩展组件
    this._registerComponent(app);

    this.appendIconCss();

    // 添加默认插件
    this.registerDefaultPlugins();

    // 注入路由
    if (this.options.router) {
      app.use(this.options.router);
    }

    // 注册头部插件
    this.registerHeaderLeftPlugins();
    this.registerHeaderRightPlugins();
    this.registerHeaderCenterPlugins();

    // 注册帮助插件
    this.registerFloatingHelpRightPlugins();

    // 外部注册自定义组件回调函数
    if (typeof this.options.registerComponents === "function") {
      await this.options.registerComponents(app);
    }

    app.mount(this.mountPoint);

    this.initialized = true;
  }

  private _registerComponent(app: App) {
    // 注册elementPlus
    app.use(ElementPlus, {
      locale: zhCnDefault,
    });
    // 注册扩展库
    /* if (window.ElementPro) {
      app.use(window.ElementPro);
    } */

    if (window.ElementPlusUi) {
      app.use(window.ElementPlusUi);
    }

    if (window.TablePro) {
      app.use(window.TablePro);
    }
  }

  /* 悬浮帮助区域 */
  private registerFloatingHelpRightPlugins() {
    const frameStore = portalStore();
    const props = { frameStore: frameStore as any };

    this.pluginManager.registerPlugin({
      id: "FloatingHelpFeedback",
      description: "反馈中心",
      sort: 51,
      type: PluginType.CUSTOM_RENDER,
      renderComponent: () => h(FloatingHelpFeedback, props),
      position: pluginPosition.FLOATING_HELP,
      extra: {
        type: "floating-help-top",
      },
      onClick: () => {
        console.log("点击了Portal FloatingHelpFeedback");
      },
    });
    this.pluginManager.registerPlugin({
      id: "FloatingSystemMessage",
      description: "信息动态",
      sort: 51,
      type: PluginType.CUSTOM_RENDER,
      renderComponent: () => h(FloatingSystemMessage, props),
      position: pluginPosition.FLOATING_HELP,
      extra: {
        type: "floating-help-content",
      },
      onClick: () => {
        console.log("点击了Portal FloatingHelpFeedback");
      },
    });
    this.pluginManager.registerPlugin({
      id: "FloatingDocument",
      description: "模块文档",
      sort: 51,
      type: PluginType.CUSTOM_RENDER,
      renderComponent: () => h(FloatingDocument, props),
      position: pluginPosition.FLOATING_HELP,
      extra: {
        type: "floating-help-content",
      },
      onClick: () => {
        console.log("点击了Portal FloatingHelpFeedback");
      },
    });
  }

  /**
	 * 注册头部左侧插件
	 * @private
	 */
  private registerHeaderLeftPlugins() {
    const frameStore = portalStore() as any;
    this.pluginManager.registerPlugin({
      id: "TenantLogoWidget",
      sort: 5,
      type: PluginType.CUSTOM_RENDER,
      renderComponent: () => h(TenantLogoWidget, { frameStore }),
      position: pluginPosition.HEADER_LEFT,
      onClick: () => {
        // console.log("点击了Portal logo");
      },
    });
    this.pluginManager.registerPlugin({
      id: "ApplicationNameWidget",
      sort: 8,
      type: PluginType.CUSTOM_RENDER,
      renderComponent: () => h(ApplicationNameWidget, { frameStore }),
      position: pluginPosition.HEADER_LEFT,
      onClick: () => {
        // console.log("点击了Portal logo");
      },
    });
  }

  /**
	 * 注册头部右侧插件
	 * @private
	 */
  private registerHeaderRightPlugins() {
    const frameStore = portalStore();
    const props = { frameStore } as any;

    this.pluginManager.registerPlugin({
      id: "TenantOrgWidget",
      description: "header组织机构切换控件",
      sort: 37,
      type: PluginType.CUSTOM_RENDER,
      renderComponent: () => h(TenantOrgWidget, props),
      position: pluginPosition.HEADER_RIGHT,
      onClick: () => {
        // console.log("点击了Portal TenantOrgWidget");
      },
    });

    this.pluginManager.registerPlugin({
      id: "AccountManagement",
      sort: 55,
      type: PluginType.CUSTOM_RENDER,
      renderComponent: () => h(AccountManagement, props),
      position: pluginPosition.HEADER_RIGHT,
      onClick: () => {
        // console.log("点击了Portal AccountManagement");
      },
    });
    this.pluginManager.registerPlugin({
      id: "KanbanSetting",
      sort: 59,
      type: PluginType.CUSTOM_RENDER,
      renderComponent: () => h(KanbanSetting, props),
      position: pluginPosition.HEADER_RIGHT,
      onClick: () => {
        // console.log("点击了Portal AccountManagement");
      },
    });
  }

  /**
	 * 注册头部中心插件
	 * @private
	 */
  private registerHeaderCenterPlugins() {
    //   pass
  }

  private registerDefaultPlugins() {
    //   pass
  }

  private appendIconCss() {
    // 创建link标签插入header内部
    const scriptElement = document.createElement("script");
    scriptElement.setAttribute("src", "https://cdn.yearrow.com/files/@cs/js-web-framework/latest/js-web-iconfont.js");
    document.head.appendChild(scriptElement);
  }
}
