import type { Component } from "vue";
import type { Icon } from "./layout-utils";

// 插件类型枚举
export enum PluginType {
  TEXT = "text",
  ICON_EXPAND = "icon-expand",
  ICON_DROPDOWN = "icon-dropdown",
  ICON_DRAWER = "icon-drawer",
  ICON_LINK = "icon-link",
}

// 插件配置接口
export interface PluginConfig {
  id: string;
  type: PluginType;
  icon?: Icon;
  text?: string;
  component?: Component;
  url?: string;
  props?: Record<string, any>;
  position?: "left" | "center" | "right"; // 仅用于header插件
  onClick?: (id: string) => void;
}

// 菜单项接口
export interface MenuItem {
  /* 菜单id */
  id: string;
  /* 父级菜单id */
  parentId: string;
  /* 菜单名称 */
  name: string;
  /* 菜单图标 */
  icon?: string;
  /* 子菜单 */
  children?: MenuItem[];

  /* 模块类型 */
  moduleType: string;
  /* 模块url */
  moduleUrl: string;
}

// 主题类型
export enum ThemeTypeValue {
  LIGHT = "light",
  DARK = "dark",
}

export type ThemeType = "light" | "dark";

// 布局状态接口
export interface LayoutState {
  headerVisible: boolean;
  sidebarVisible: boolean;
  navigationVisible: boolean;
  floatingHelpVisible: boolean;
  theme: ThemeType;
  activeMenuId: string;
  loadCustomConfig: boolean;
}

// 布局选项接口
export interface LayoutOptions {
  defaultTheme?: ThemeType;
  sidebarCollapsed?: boolean;
  headerVisible?: boolean;
  sidebarVisible?: boolean;
  helpVisible?: boolean;
  loadCustomConfig?: boolean;
  defaultMenu?: MenuItem[];
}
