import type { PropType } from "vue";
import type { IconLinkPluginConfig } from "../plugin-type";
import { ElTooltip } from "element-plus";
import { defineComponent, h } from "vue";
import { webFrameworkEvent } from "../../../../utils/web-framework-event";

export default defineComponent({
  name: "PluginIconLink",
  props: {
    config: {
      type: Object as PropType<IconLinkPluginConfig>,
      required: true,
    },
  },
  setup(props) {
    const handleClick = () => {
      webFrameworkEvent.emit(`plugin.${props.config.id}.link.click`, props.config.url);
    };

    return () => {
      if (!props.config.tooltip) {
        return (
          <a
            href={props.config.url}
            target={props.config.target || "_blank"}
            onClick={handleClick}
            class="layout-plugin-icon-link-wrapper"
          >
            {h(props.config.icon)}
          </a>
        );
      }
      return (
        <ElTooltip
          effect="dark"
          content={props.config.tooltip || ""}
          placement={props.config?.placement || "top"}
        >
          <a
            href={props.config.url}
            target={props.config.target || "_blank"}
            onClick={handleClick}
            class="layout-plugin-icon-link-wrapper"
          >
            {h(props.config.icon)}
          </a>
        </ElTooltip>
      );
    };
  },
});
