import type { ComputedRef } from "vue";
import type {
  DataType,
  IPublicApplicationType,
  IPublicContextStateType,
  IPublicFramePortalType,
  IPublicMenuType,
  IPublicOrgNodeType,
  IPublicPortalConfigType,
  IPublicUserType,
  QueryParamsType,
} from "../types";
// 导入缺失的类型
import { isEmpty } from "lodash-es";
import { defineStore } from "pinia";

import { computed, ref } from "vue";

// 定义 store 返回值的完整类型接口
export interface PortalStoreType {
  // 状态
  $context: IPublicContextStateType;
  queryData: Partial<QueryParamsType>;
  menus: IPublicMenuType[];
  menuItems: IPublicMenuType[];
  currentMenu: Partial<IPublicMenuType>;
  parentMenu: IPublicMenuType | null;
  orgRoot: IPublicOrgNodeType;
  msgNum: number;
  applications: IPublicApplicationType[];
  portalConfig: IPublicPortalConfigType;
  isRefresh: boolean;

  // getters
  queryParams: ComputedRef<Partial<QueryParamsType>>;
  user: ComputedRef<IPublicUserType>;
  permissions: ComputedRef<string[]>;

  // actions
  setContext: (portalCtx: Partial<IPublicContextStateType>) => void;
  setQueryParams: (queryParams: Partial<QueryParamsType>) => void;
  setOrgRoot: (orgRoot: Partial<IPublicOrgNodeType>) => void;
  setMenus: (
    menus: IPublicMenuType[],
    menuItems: IPublicMenuType[],
    currentMenu: {
      menu: Partial<IPublicMenuType>;
      parentMenu: Partial<IPublicMenuType> | null;
    },
  ) => void;
  setApplications: (applications: IPublicApplicationType[]) => void;
  setPortalConfig: (portalConfig: IPublicPortalConfigType) => void;
  setIsRefresh: (val: boolean) => void;
}

export const portalStore = defineStore("portalStore", () => {
  // 状态定义
  const $context = ref<Partial<IPublicContextStateType>>({
    portalLogo: "",
    portalName: "",
    appIcon: "",
    appName: "",
    applicationId: "",
    orgId: 0,
    orgShortName: "",
    orgType: "",
    extType: "",
    parentId: 0,
    permissions: [],
    productCode: "",
    userId: "",
    userName: "",
    tenantId: 0,
    tenantCode: "",
    tenantName: "",
    internalUser: false,
    workstationApp: true,
    fullId: "",
    orgName: "",
    orgFullName: "",
    moduleId: "",
    moduleName: "",
    moduleUrl: "",
    moduleCode: "",
    // 根据类型定义补充缺失的字段
    productName: "",
    products: [],
    phoneNumber: "",
    userAvatarUrl: "",
    realName: "",
  });

  const queryData = ref<Partial<IPublicFramePortalType["queryData"]>>({});
  const menus = ref<IPublicMenuType[]>([]);
  const menuItems = ref<IPublicMenuType[]>([]);
  const currentMenu = ref<IPublicFramePortalType["currentMenu"]>({});
  const parentMenu = ref<IPublicFramePortalType["parentMenu"]>(null);
  const orgRoot = ref<Partial<IPublicOrgNodeType>>({});
  const msgNum = ref<number>(0);
  const applications = ref<IPublicApplicationType[]>([]);
  const portalConfig = ref<Partial<IPublicPortalConfigType>>({});
  const lastProject = ref<DataType>({});
  const isRefresh = ref<boolean>(false);

  // Getters 定义
  const queryParams = computed(() => queryData.value);

  const user = computed<IPublicUserType>(() => ({
    userId: $context.value.userId,
    userName: $context.value.userName,
  }));

  const permissions = computed(() => $context.value.permissions);

  // Actions 定义
  function setContext(portalCtx: Partial<IPublicContextStateType>) {
    if (isEmpty(portalCtx)) {
      console.error("Portal context cannot be empty.");
      return;
    }
    $context.value = portalCtx;
  }

  function setQueryParams(queryParams: Partial<QueryParamsType>) {
    queryData.value = queryParams;
  }

  function setOrgRoot(orgRootValue: Partial<IPublicOrgNodeType>) {
    orgRoot.value = { ...orgRoot.value, ...orgRootValue };
  }

  function setMenus(
    menusValue: IPublicMenuType[],
    menuItemsValue: IPublicMenuType[],
    currentMenuValue: { menu: IPublicMenuType; parentMenu: IPublicMenuType | null },
  ) {
    menus.value = menusValue;
    menuItems.value = menuItemsValue;
    currentMenu.value = currentMenuValue.menu;
    parentMenu.value = currentMenuValue.parentMenu;
  }

  function setApplications(applicationsValue: IPublicApplicationType[]) {
    applications.value = applicationsValue;
  }

  function setPortalConfig(portalConfigValue: IPublicPortalConfigType) {
    portalConfig.value = portalConfigValue;
  }

  function setLastProject(val: DataType) {
    lastProject.value = val;
  }

  function setIsRefresh(val: boolean) {
    isRefresh.value = val;
  }

  // 导出状态、getters 和 actions
  return {
    // 状态
    $context,
    queryData,
    menus,
    menuItems,
    currentMenu,
    parentMenu,
    orgRoot,
    msgNum,
    applications,
    portalConfig,
    isRefresh,
    // getters
    queryParams,
    user,
    permissions,
    // actions
    setContext,
    setQueryParams,
    setOrgRoot,
    setMenus,
    setApplications,
    setPortalConfig,
    setLastProject,
    setIsRefresh,
  };
});
