import { ElMessage } from "element-plus";
import { computed, defineComponent, onMounted, ref } from "vue";
import { apiPortal } from "../../../api/api-portal";
import { IPublicFramePortalType, IPublicOrgNodeType } from "../../../types";
import { redirectUrl } from "../../../utils/redirect-url";
import { nodeIconClass } from "./icon-util";
import YqSearchTreeSelect from "./tree/search-tree-select.vue";

export const PortalOrgSelect = defineComponent({
  name: "PortalOrgSelect",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(props) {
    const orgId = ref(props.frameStore.$context.orgId);
    const orgName = ref(props.frameStore.$context.orgShortName);

    const defaultExpandedKeys = ref([]);
    // 重新初始化，不影响store里的值
    const rootNode = ref<Partial<IPublicOrgNodeType>>({});
    const curApplicationId = computed(() => {
      return props.frameStore?.currentApplication?.id ?? props.frameStore.$context.applicationId;
    });

    const methods = {
      init: async () => {
        const orgRootResult = await apiPortal.getUserValidOrgTrees({
          params: {
            applicationId: curApplicationId.value,
            parentId: -1,
          },
        });
        if (orgRootResult.result.length === 0) {
          return;
        }
        const orgRoot = orgRootResult.result;

        // 重新设置上下文的根节点
        props.frameStore.setOrgRoot(orgRoot[0]);
        rootNode.value = Object.assign({}, props.frameStore.orgRoot, {
          disabled: !orgRoot[0].isValid,
        });
        if (props.frameStore.$context.fullId) {
          const arr = props.frameStore.$context.fullId.split("|");
          defaultExpandedKeys.value = arr.map(id => id);
        }
      },
      loadData: async (params, resolve) => {
        if (props.frameStore.$context.orgId) {
          params.applicationId = props.frameStore.$context.applicationId;
          const orgsResult = await apiPortal.getUserValidOrgTrees({
            params,
          });
          const orgs = orgsResult.result;
          orgs.forEach((org) => {
            org.disabled = !org.isValid;
          });
          resolve(orgs);
        } else {
          resolve([]);
        }
      },
      loadNode: (node, resolve) => {
        const params = {
          preset: "tree",
          parentId: node.id,
          offset: node.offset,
          limit: node.limit,
        };
        methods.loadData(params, resolve);
      },
      loadMore: (node, resolve) => {
        const params = {
          preset: "tree",
          parentId: node.id,
          offset: node.offset,
          limit: node.limit,
        };
        methods.loadData(params, resolve);
      },
      loadSearchData: (filter, resolve) => {
        const params = {
          preset: "search",
          isValid: true,
          key: "",
        };
        if (filter) {
          params.key = filter;
        }
        methods.loadData(params, resolve);
      },
      selectChange: (node) => {
        if (node.isValid) {
          orgName.value = node.shortName || node.name || node.fullName || "";
          if (node.id === props.frameStore.$context.orgId) {
            console.info("组织机构未变化");
            return;
          }

          window.location.href = redirectUrl({
            url: location.origin + location.pathname,
            // applicationId: props.frameStore.$context.applicationId,
            // moduleId: props.frameStore.$context.moduleId,
            orgId: node.id,
          });
          // 重新加载上下文数据
          // initWebContext(node.id);
        } else {
          console.warn("[web-framework]无权限访问组织", node);
          ElMessage.warning("当前组织机构无访问权限");
        }
      },
    };

    onMounted(() => {
      if (props.frameStore.$context.orgId) {
        methods.init();
      }
    });

    return () => {
      return (
        <YqSearchTreeSelect
          popoverClass="portal-tenant-org-select-popover"
          v-model={orgId.value}
          defaultText={orgName.value}
          currentSize={20}
          width="430px"
          dropdown-width="450px"
          search-placeholder="请输入检索信息"
          rootNode={rootNode.value}
          expand-first={true}
          defaultProps={{
            label: "shortName",
            value: "id",
            disabled: "disabled",
          }}
          defaultExpandedKeys={defaultExpandedKeys.value}
          onLoadNode={methods.loadNode}
          onLoadSearchData={methods.loadSearchData}
          onSelectChange={methods.selectChange}
        >
          {{
            treeitem: ({ row }) => {
              return row.shortName;
            },
            listitem: ({ row }: { row: IPublicOrgNodeType }) => {
              return (
                <div class="list-item">
                  <i class={nodeIconClass(row.extType)} />
                  <div class="list-item-org">
                    <div class="title">
                      {row.shortName}
                    </div>
                    <div class="second-title">
                      {row.fullName}
                    </div>
                  </div>
                </div>
              );
            },
          }}
        </YqSearchTreeSelect>
      );
    };
  },
});
