/**
 * PortalBridge - 子应用通信桥接SDK
 * @fileoverview 提供给 iframe 子应用使用的轻量通信类（单例模式）
 *
 * 功能：
 * 1. openTab - 在父应用中打开新的Tab页签
 * 2. closeTab - 关闭Tab页签（自身或指定Tab）
 * 3. setEditing - 设置当前页签的编辑状态
 * 4. showMessage - 在父应用中弹出 ElMessage 提示
 * 5. onBeforeClose - 注册关闭前确认回调
 * 6. onActivate / onDeactivate - 监听页签激活/停用事件
 * 7. getContext - 获取父应用 portalStore.$context 上下文数据
 *
 * 零外部依赖，仅使用原生 postMessage API
 *
 * @example
 * ```typescript
 * const bridge = PortalBridge.getInstance({ tabId: 'menu-xxx' });
 *
 * bridge.openTab({
 *   menuId: '123', menuName: '订单详情',
 *   moduleId: 'order', moduleUrl: 'https://xxx.com/order',
 *   applicationId: 'app1', applicationName: '订单系统',
 * });
 *
 * bridge.closeTab(); // 关闭当前Tab
 * bridge.closeTab({ tabId: 'menu-456', force: true }); // 强制关闭指定Tab
 *
 * bridge.setEditing(true);
 * bridge.showMessage({ type: 'success', message: '保存成功' });
 *
 * bridge.onBeforeClose(async () => {
 *   return confirm('有未保存的内容，确定离开？');
 * });
 * ```
 */

import type {
  BeforeCloseData,
  CloseTabData,
  GetContextResponseData,
  OpenTabData,
  PortalBridgeOptions,
  PortalMessage,
  RedirectLoginData,
  ShowMessageData,
} from "./types";
import { PortalMessageType } from "./types";

type BeforeCloseHandler = () => boolean | Promise<boolean>;
type LifecycleHandler = () => void;

class PortalBridge {
  private static instance: PortalBridge | null = null;

  private tabId: string;
  private _debug: boolean;
  private beforeCloseHandler: BeforeCloseHandler | null = null;
  private activateHandlers: LifecycleHandler[] = [];
  private deactivateHandlers: LifecycleHandler[] = [];
  private unmountHandlers: LifecycleHandler[] = [];

  /** 缓存的父应用上下文数据 */
  private contextData: Partial<GetContextResponseData> = {};

  /** 绑定的 message 事件处理函数引用，用于销毁时移除 */
  private boundMessageHandler: (event: MessageEvent) => void;

  private constructor(options: PortalBridgeOptions = {}) {
    this.tabId = options.tabId || this.resolveTabIdFromUrl();
    this._debug = options.debug || false;

    this.boundMessageHandler = this.handleMessage.bind(this);
    window.addEventListener("message", this.boundMessageHandler);

    // 构造时自动请求父应用上下文数据
    this.requestContext();

    this.log("PortalBridge 初始化完成, tabId:", this.tabId);
  }

  /**
   * 获取单实例
   * @param options 首次调用时的配置项，后续调用忽略
   */
  static getInstance(options?: PortalBridgeOptions): PortalBridge {
    if (!PortalBridge.instance) {
      PortalBridge.instance = new PortalBridge(options);
    }
    return PortalBridge.instance;
  }

  /**
   * 重置单例（一般用于测试或需要重新初始化的场景）
   */
  static resetInstance(): void {
    if (PortalBridge.instance) {
      PortalBridge.instance.destroy();
      PortalBridge.instance = null;
    }
  }

  // ===== 公开API =====

  /**
   * 获取当前 tabId
   */
  getTabId(): string {
    return this.tabId;
  }

  /**
   * 获取当前 debug 状态
   */
  get isDebug(): boolean {
    return this._debug;
  }

  /**
   * 开启调试模式
   */
  enableDebug(): void {
    this._debug = true;
    this.log("调试模式已开启");
  }

  /**
   * 关闭调试模式
   */
  disableDebug(): void {
    this.log("调试模式已关闭");
    this._debug = false;
  }

  /**
   * 在父应用中打开新的Tab页签
   * @param tabInfo Tab信息（menuId、menuName、moduleUrl 等为必填）
   */
  openTab(tabInfo: OpenTabData): void {
    this.postToParent(PortalMessageType.OPEN_TAB, tabInfo);
  }

  /**
   * 关闭Tab页签
   * @param options 关闭选项
   * @param options.tabId 要关闭的Tab ID，不传则关闭当前Tab（自身）
   * @param options.force 是否强制关闭（忽略编辑状态），默认 false
   */
  closeTab(options?: CloseTabData): void {
    this.postToParent(PortalMessageType.CLOSE_TAB, {
      tabId: options?.tabId || this.tabId,
      force: options?.force || false,
    });
  }

  /**
   * 设置当前页签的编辑状态
   * @param isEditing 是否处于编辑状态
   * @param data 可选的编辑状态附加数据
   */
  setEditing(isEditing: boolean, data?: Record<string, any>): void {
    this.postToParent(PortalMessageType.SET_EDITING, {
      tabId: this.tabId,
      isEditing,
      data,
    });
  }

  /**
   * 在父应用中弹出 ElMessage 提示
   * @param options 消息选项
   */
  showMessage(options: ShowMessageData): void {
    this.postToParent(PortalMessageType.SHOW_MESSAGE, options);
  }

  /**
   * 请求父应用重定向至登录页
   * 典型场景：子应用检测到会话过期（如401响应），通知父应用跳转登录页
   * @param options 重定向选项
   * @param options.loginUrl 登录页地址，不传则由父应用使用默认登录页地址
   * @param options.reason 重定向原因说明（可选，用于日志记录）
   *
   * @example
   * ```typescript
   * // 使用父应用默认登录页
   * bridge.redirectLogin();
   *
   * // 指定登录页地址
   * bridge.redirectLogin({ loginUrl: 'https://sso.example.com/login' });
   *
   * // 携带原因说明
   * bridge.redirectLogin({ reason: '会话已过期，请重新登录' });
   * ```
   */
  redirectLogin(options?: RedirectLoginData): void {
    this.postToParent(PortalMessageType.REDIRECT_LOGIN, {
      loginUrl: options?.loginUrl,
      reason: options?.reason || "session expired",
    });
  }

  /**
   * 注册关闭前确认回调
   * 当父应用尝试关闭当前Tab时，会先调用此回调
   * 返回 true 允许关闭，返回 false 阻止关闭
   * @param handler 回调函数
   */
  onBeforeClose(handler: BeforeCloseHandler): void {
    this.beforeCloseHandler = handler;
  }

  /**
   * 监听Tab被激活事件
   * @param handler 回调函数
   */
  onActivate(handler: LifecycleHandler): void {
    this.activateHandlers.push(handler);
  }

  /**
   * 监听Tab被停用事件
   * @param handler 回调函数
   */
  onDeactivate(handler: LifecycleHandler): void {
    this.deactivateHandlers.push(handler);
  }

  /**
   * 监听Tab被卸载事件
   * @param handler 回调函数
   */
  onUnmount(handler: LifecycleHandler): void {
    this.unmountHandlers.push(handler);
  }

  /**
   * 销毁实例，移除事件监听
   */
  destroy(): void {
    window.removeEventListener("message", this.boundMessageHandler);
    this.beforeCloseHandler = null;
    this.activateHandlers = [];
    this.deactivateHandlers = [];
    this.unmountHandlers = [];
    this.contextData = {};
    this.log("PortalBridge 已销毁");
  }

  /**
   * 获取父应用的上下文数据（portalStore.$context）
   *
   * 同步返回缓存的上下文数据。PortalBridge 初始化时会自动向父应用请求，
   * 响应到达后缓存到本地。首次调用时如果父应用尚未响应，可能返回空对象。
   *
   * @returns 上下文数据的 Partial 对象
   *
   * @example
   * ```typescript
   * const context = bridge.getContext();
   * console.log(context.userId, context.userName);
   * ```
   */
  getContext(): Partial<GetContextResponseData> {
    return this.contextData;
  }

  // ===== 内部方法 =====

  /**
   * 向父应用请求上下文数据（构造时自动调用）
   */
  private requestContext(): void {
    this.postToParent(PortalMessageType.GET_CONTEXT, { tabId: this.tabId });
  }

  /**
   * 处理来自父应用的消息
   */
  private handleMessage(event: MessageEvent): void {
    const message = event.data as PortalMessage;
    if (!message || !message.type || message.source !== "main-app") {
      return;
    }

    switch (message.type) {
      case PortalMessageType.BEFORE_CLOSE:
        this.handleBeforeClose(message.data as BeforeCloseData);
        break;
      case PortalMessageType.TAB_ACTIVATE:
        this.log("Tab 激活");
        this.activateHandlers.forEach(h => h());
        break;
      case PortalMessageType.TAB_DEACTIVATE:
        this.log("Tab 停用");
        this.deactivateHandlers.forEach(h => h());
        break;
      case PortalMessageType.TAB_UNMOUNT:
        this.log("Tab 卸载");
        this.unmountHandlers.forEach(h => h());
        break;
      case PortalMessageType.GET_CONTEXT_RESPONSE:
        this.contextData = message.data as GetContextResponseData;
        this.log("上下文数据已缓存:", this.contextData);
        break;
    }
  }

  /**
   * 处理关闭前确认请求
   */
  private async handleBeforeClose(data: BeforeCloseData): Promise<void> {
    // 只处理属于自己的关闭请求
    if (data.tabId && data.tabId !== this.tabId) {
      return;
    }

    let allow = true;
    let message: string | undefined;

    if (this.beforeCloseHandler) {
      try {
        allow = await this.beforeCloseHandler();
      } catch (error) {
        this.log("onBeforeClose 回调执行异常:", error);
        allow = true; // 异常时默认允许关闭
      }
    }

    // 回复父应用（兼容已有协议格式）
    this.postToParent(PortalMessageType.BEFORE_CLOSE_RESPONSE, {
      tabId: this.tabId,
      allow,
      message,
    });
  }

  /**
   * 向父应用发送消息
   */
  private postToParent(type: string, data: any): void {
    this.log("发送消息给父应用:", type, data);
    if (window.parent === window) {
      this.log("当前不在iframe内，消息未发送:", type, data);
      return;
    }

    const message: PortalMessage = {
      type,
      data,
      source: "child-app",
      timestamp: Date.now(),
    };

    window.parent.postMessage(message, "*");
    this.log("发送消息:", type, data);
  }

  /**
   * 从URL参数中解析tabId（menuId）
   */
  private resolveTabIdFromUrl(): string {
    try {
      const params = new URLSearchParams(window.location.search);
      return params.get("menuId") || params.get("tabId") || "";
    } catch {
      return "";
    }
  }

  /**
   * 调试日志
   */
  private log(...args: any[]): void {
    if (this._debug) {
      console.log("[PortalBridge]", ...args);
    }
  }
}

/** 单例实例，直接导入使用 */
export const portalBridge = PortalBridge.getInstance();
