import { Plus, Setting } from "@element-plus/icons-vue";
import { defineComponent, onMounted, reactive } from "vue";
import { useCsNamespace } from "../../../hooks";
import { IPublicFramePortalType } from "../../../types";
import { useKanbanTheme } from "../../hooks/use-kanban-theme";
import fresh from "./fresh.png";
import tech from "./tech.png";
import "./kanban-widget-style.less";

export const KanbanSetting = defineComponent({
  name: "KanbanSetting",
  props: {
    frameStore: {
      type: Object as () => IPublicFramePortalType,
      required: true,
    },
  },
  setup(_props) {
    const ns = useCsNamespace("kanban-setting");
    const { setTheme } = useKanbanTheme();
    const state = reactive({
      drawer: false,
      /* 刷新频率 */
      refreshFrequency: 10,
    });

    const methods = {
      toggleDrawer(): void {
        state.drawer = !state.drawer;
      },
      renderBaseConfig: () => {
        return (
          <div class={ns.b("base-config")}>
            <el-divider>基础设置</el-divider>
            <el-form>
              <el-form-item label="刷新频率">
                <el-select v-model={state.refreshFrequency}>
                  <el-option label="10分钟" value={10}></el-option>
                  <el-option label="30分钟" value={30}></el-option>
                  <el-option label="60分钟" value={60}></el-option>
                </el-select>
              </el-form-item>
              <el-form-item label="主题设置" label-position="top">
                <el-row gutter={10}>
                  <el-col span={12}>
                    <div class={ns.b("theme-item")}>
                      <img
                        onClick={(e: MouseEvent) => setTheme("dark", e)}
                        src={tech}
                        alt=""
                        class={ns.b("theme-item-img")}
                        width="136"
                        height="82"
                      />
                      <span class={ns.b("theme-item-text")}>科技</span>
                    </div>
                  </el-col>
                  <el-col span={12}>
                    <div class={ns.b("theme-item")}>
                      <img
                        onClick={(e: MouseEvent) => setTheme("light", e)}
                        src={fresh}
                        alt=""
                        class={ns.b("theme-item-img")}
                        width="136"
                        height="82"
                      />
                      <span class={ns.b("theme-item-text")}>清新</span>
                    </div>
                  </el-col>
                </el-row>
              </el-form-item>
            </el-form>
          </div>
        );
      },
      renderTabConfig: () => {
        return (
          <div class={ns.b("tab-config")}>
            <el-divider>页签设置</el-divider>
            <div class={ns.b("tab-config-content")}>

            </div>
            <el-button type="primary" plain text>
              <el-icon><Plus /></el-icon>
&nbsp;创建新页签
            </el-button>
          </div>
        );
      },
      renderDrawer: () => {
        if (!state.drawer) {
          return null;
        }
        return (
          <el-drawer
            append-to-body
            v-model={state.drawer}
            title="设置"
            size={300}
          >
            <yq-flex-box
              item-num={2}
              is-row={false}
              item-config={[
                {
                  tag: "item-1",
                  isFixed: false,
                  size: "",
                  paddingSize: "large",
                  clearPadding: ["bottom"],
                },
                {
                  tag: "item-2",
                  isFixed: true,
                  size: "",
                  paddingSize: "large",
                },
              ]}
            >
              {{
                "item-1": () => {
                  return (
                    <el-scrollbar height="100%">
                      {methods.renderBaseConfig()}
                      {methods.renderTabConfig()}
                    </el-scrollbar>
                  );
                },
                "item-2": () => {
                  return (
                    <yq-flex-line>
                      {{
                        right: () => {
                          return (
                            <>
                              <el-button link>
                                重置为默认
                              </el-button>
                              <el-button type="primary">保存</el-button>
                            </>
                          );
                        },
                      }}
                    </yq-flex-line>
                  );
                },
              }}
            </yq-flex-box>

          </el-drawer>
        );
      },
    };

    onMounted(() => {

    });

    return () => {
      return (
        <div
          class={[ns.b(), "layout-plugin-icon-link-wrapper"]}
          onClick={methods.toggleDrawer}
        >
          { methods.renderDrawer() }
          <el-icon><Setting /></el-icon>
        </div>
      );
    };
  },
});
